import{_ as e,o as a,c as i,ag as o}from"./chunks/framework.CxkNbRKf.js";const n="/nada-documentation/images/image52.png",s="/nada-documentation/images/image53.png",r="/nada-documentation/images/image54.png",b=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/dashboard.md","filePath":"admin-guide/web-ui/dashboard.md","lastUpdated":1786379412000}'),d={name:"admin-guide/web-ui/dashboard.md"};function l(h,t,c,p,g,m){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><h2 id="using-the-administrator-interface" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p>After logging in to the site with administrator credentials, you will be taken to the Dashboard page of the Administrator interface. The page also includes the menu that provides access to all sections of the administrator interface.</p><p><img src="'+n+'" alt=""></p><p>The Dashboard provides a quick glance summary for administrators to get an overall picture of the content of the catalog as well as of pending tasks for the administrator.</p><p><img src="'+s+'" alt=""></p><p>Box 1 (<em>Central Data Catalog</em>) provides information on the total number of entries (of any type) listed in the catalog. It distinguishes the entries that are &quot;owned&quot; by the Central Catalog (entries managed by the Central Catalog administrator, that are not owned by a specific collection or &quot;sub-catalog) from the &quot;linked&quot; entries (those that are owned by a collection but displayed in the Central catalog). It also distinguishes the entries that are published (i.e., visible by visitors of the catalog site) from those that are in draft (&quot;unpublished&quot;) mode, only visible to the administrators and reviewers. The box also contains some warnings. It will for example indicate the number of micro-datasets published as &quot;Public Use Files&quot; but for which no data files are available in the catalog, or the number of microdata entries for which no document of type &quot;questionnaire&quot; is provided.</p><p>The button Manage studies will open the catalog administration page that provides the tools for adding, editing, and deleting catalog entries (described in section Manage studies of this Guide). The button History provides a listing of additions to the Collection (in this case the Central Catalog), with information on the date when the entry was created and last modified (the buttons displayed in this page are described in section Manage collections).</p><p><img src="'+r+'" alt=""></p><p>Box 2 (<em>Collection: [collection name]</em>) will only be displayed when your catalog contains Collections. One box will be displayed per collection, with the same information as in Box 1. Two additional buttons are provided, which provide access respectively to a page allowing the catalog administrator(s) with appropriate credentials to edit the permissions attached to the collection, and to edit the description of the collection (see Managing collections section).</p><p>Box 3 (<em>Users</em>) provides summary information on the number of users registered to the catalog (which includes not only the catalog and collections administrators, but also users who registered to the catalog to obtain or request access to non-public data).</p><p>Box 4 (<em>Recently updated studies</em>) is a listing of the most-recently added (or modified) entries in the catalog, with a link to the entry page allowing administrators to edit it.</p><h2 id="using-the-api" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>Related endpoints:</p><p><a href="https://ihsn.github.io/nada-api-redoc/catalog-admin/#operation/listDatasets" target="_blank" rel="noreferrer">https://ihsn.github.io/nada-api-redoc/catalog-admin/#operation/listDatasets</a></p><p><a href="https://ihsn.github.io/nada-api-redoc/catalog-admin/#operation/singleDataset" target="_blank" rel="noreferrer">https://ihsn.github.io/nada-api-redoc/catalog-admin/#operation/singleDataset</a></p><p>Using R:</p><p>The content of the dashboard can be generated using the API as follows:</p><p>Datasets</p>',19)])])}const f=e(d,[["render",l]]);export{b as __pageData,f as default};
